supplier_code = #{supplierCode}, supplier_name = #{supplierName}, supplier_type = #{supplierType}, contact_person = #{contactPerson}, contact_phone = #{contactPhone}, address = #{address}, iso_cert_no = #{isoCertNo}, iso_expire_date = #{isoExpireDate}, iso_cert_file_url = #{isoCertFileUrl}, env_cert_no = #{envCertNo}, env_expire_date = #{envExpireDate}, env_cert_file_url = #{envCertFileUrl}, quality_report_no = #{qualityReportNo}, quality_report_expire_date = #{qualityReportExpireDate}, quality_report_file_url = #{qualityReportFileUrl}, warning_days = #{warningDays}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
